{"version":3,"file":"main.jsdbx","sources":["../../src/client/services/DashboardService.js","../../src/client/components/ExportDefinitionsOverview.jsx","../../src/client/components/ExecutionMetrics.jsx","../../src/client/components/ErrorInsights.jsx","../../src/client/components/ConfigurationQuality.jsx","../../src/client/components/TopExportProfiles.jsx","../../src/client/components/ExportDefinitionsOverview.css","../../src/client/components/ExecutionMetrics.css","../../src/client/Dashboard.css","../../src/client/main.jsx","../../src/client/Dashboard.jsx"],"sourcesContent":["export class DashboardService {
  constructor() {
    // Get table names from now.config.json or use dynamic discovery
    this.scopeName = 'x_271493_dynamic_c';
    this.tables = {
      exportDefinition: `${this.scopeName}_export_definition`,
      exportMapping: `${this.scopeName}_export_mapping`, 
      csvRelatedSource: `${this.scopeName}_csv_related_source`,
      exportLog: `${this.scopeName}_export_log`
    };
  }

  async loadAllData() {
    try {
      const [definitions, mappings, relatedSources, executionLogs] = await Promise.all([
        this.getExportDefinitions(),
        this.getExportMappings(),
        this.getRelatedSources(),
        this.getExecutionLogs()
      ]);

      return {
        definitions,
        mappings,
        relatedSources,
        executionLogs
      };
    } catch (error) {
      console.error('Error loading dashboard data:', error);
      throw error;
    }
  }

  async getExportDefinitions() {
    return this._fetchTableData(this.tables.exportDefinition, {
      sysparm_display_value: 'all',
      sysparm_fields: 'sys_id,export_name,active,target_table,description,sys_created_on,sys_updated_on,sys_updated_by'
    });
  }

  async getExportMappings() {
    return this._fetchTableData(this.tables.exportMapping, {
      sysparm_display_value: 'all',
      sysparm_fields: 'sys_id,export_definition,header_label,source_type,order_number'
    });
  }

  async getRelatedSources() {
    return this._fetchTableData(this.tables.csvRelatedSource, {
      sysparm_display_value: 'all',
      sysparm_fields: 'sys_id,export_definition,alias,table,relationship_field'
    });
  }

  async getExecutionLogs(limit = 1000) {
    const thirtyDaysAgo = new Date();
    thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
    const encodedQuery = `execution_start>javascript:gs.dateGenerate('${thirtyDaysAgo.toISOString().split('T')[0]}','00:00:00')`;

    return this._fetchTableData(this.tables.exportLog, {
      sysparm_display_value: 'all',
      sysparm_fields: 'sys_id,export_definition,execution_start,execution_end,duration_ms,records_exported,success,error_message,user',
      sysparm_query: encodedQuery,
      sysparm_limit: limit,
      sysparm_order_by: '-execution_start'
    });
  }

  async getRecentExecutionLogs(limit = 50) {
    return this._fetchTableData(this.tables.exportLog, {
      sysparm_display_value: 'all',
      sysparm_fields: 'sys_id,export_definition,execution_start,duration_ms,records_exported,success,error_message',
      sysparm_limit: limit,
      sysparm_order_by: '-execution_start'
    });
  }

  async getExecutionMetricsByDay(days = 30) {
    const startDate = new Date();
    startDate.setDate(startDate.getDate() - days);
    const encodedQuery = `execution_start>javascript:gs.dateGenerate('${startDate.toISOString().split('T')[0]}','00:00:00')`;

    return this._fetchTableData(this.tables.exportLog, {
      sysparm_display_value: 'all',
      sysparm_fields: 'execution_start,success,duration_ms,records_exported',
      sysparm_query: encodedQuery,
      sysparm_order_by: 'execution_start'
    });
  }

  async getErrorAnalytics() {
    const sevenDaysAgo = new Date();
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
    const encodedQuery = `success=false^execution_start>javascript:gs.dateGenerate('${sevenDaysAgo.toISOString().split('T')[0]}','00:00:00')`;

    return this._fetchTableData(this.tables.exportLog, {
      sysparm_display_value: 'all',
      sysparm_fields: 'sys_id,export_definition,execution_start,error_message',
      sysparm_query: encodedQuery,
      sysparm_limit: 100,
      sysparm_order_by: '-execution_start'
    });
  }

  async _fetchTableData(tableName, params = {}) {
    try {
      const searchParams = new URLSearchParams(params);
      const response = await fetch(`/api/now/table/${tableName}?${searchParams.toString()}`, {
        method: 'GET',
        headers: {
          'Accept': 'application/json',
          'X-UserToken': window.g_ck
        }
      });

      if (!response.ok) {
        let errorMessage = `HTTP ${response.status}: ${response.statusText}`;
        try {
          const errorData = await response.json();
          if (errorData.error && errorData.error.message) {
            errorMessage = errorData.error.message;
          }
        } catch (e) {
          // Ignore JSON parse errors
        }
        throw new Error(errorMessage);
      }

      const data = await response.json();
      return data.result || [];
    } catch (error) {
      console.error(`Error fetching data from ${tableName}:`, error);
      throw new Error(`Failed to fetch data from ${tableName}: ${error.message}`);
    }
  }

  // Helper methods for data processing
  extractValue(field) {
    return typeof field === 'object' ? field.value : field;
  }

  extractDisplayValue(field) {
    return typeof field === 'object' ? field.display_value : field;
  }

  groupByDate(logs, dateField = 'execution_start') {
    const grouped = {};
    logs.forEach(log => {
      const dateValue = this.extractDisplayValue(log[dateField]);
      if (dateValue) {
        const date = dateValue.split(' ')[0]; // Extract just the date part
        if (!grouped[date]) {
          grouped[date] = [];
        }
        grouped[date].push(log);
      }
    });
    return grouped;
  }

  calculateSuccessRate(logs) {
    if (logs.length === 0) return 0;
    const successful = logs.filter(log => String(log.success) === 'true').length;
    return (successful / logs.length) * 100;
  }

  calculateAverageMetric(logs, field) {
    const values = logs
      .map(log => parseFloat(this.extractValue(log[field])) || 0)
      .filter(val => val > 0);

    if (values.length === 0) return 0;
    return values.reduce((sum, val) => sum + val, 0) / values.length;
  }
}","import React, { useMemo } from 'react';
import './ExportDefinitionsOverview.css';

export default function ExportDefinitionsOverview({ definitions }) {
  const stats = useMemo(() => {
    const total = definitions.length;
    const active = definitions.filter(def => String(def.active) === 'true').length;
    const inactive = total - active;

    const recentlyModified = definitions
      .sort((a, b) => {
        const dateA = typeof a.sys_updated_on === 'object' ? a.sys_updated_on.value : a.sys_updated_on;
        const dateB = typeof b.sys_updated_on === 'object' ? b.sys_updated_on.value : b.sys_updated_on;
        return new Date(dateB) - new Date(dateA);
      })
      .slice(0, 5);

    return { total, active, inactive, recentlyModified };
  }, [definitions]);

  const getDisplayValue = (field) => {
    return typeof field === 'object' ? field.display_value : field;
  };

  const getValue = (field) => {
    return typeof field === 'object' ? field.value : field;
  };

  return (
    <div className="export-definitions-overview">
      <div className="stats-grid">
        <div className="stat-card total">
          <div className="stat-number">{stats.total}</div>
          <div className="stat-label">Total Definitions</div>
        </div>

        <div className="stat-card active">
          <div className="stat-number">{stats.active}</div>
          <div className="stat-label">Active</div>
        </div>

        <div className="stat-card inactive">
          <div className="stat-number">{stats.inactive}</div>
          <div className="stat-label">Inactive</div>
        </div>
      </div>

      <div className="charts-section">
        <div className="donut-chart-container">
          <h4>Active vs Inactive Distribution</h4>
          <div className="donut-chart">
            <div className="donut-segment active-segment" 
                 style={{ 
                   '--percentage': stats.total > 0 ? (stats.active / stats.total) * 100 : 0 
                 }}>
              <div className="donut-center">
                <span className="donut-total">{stats.total}</span>
                <span className="donut-label">Total</span>
              </div>
            </div>
          </div>
          <div className="donut-legend">
            <div className="legend-item">
              <span className="legend-color active-color"></span>
              <span>Active ({stats.active})</span>
            </div>
            <div className="legend-item">
              <span className="legend-color inactive-color"></span>
              <span>Inactive ({stats.inactive})</span>
            </div>
          </div>
        </div>

        <div className="recent-modifications">
          <h4>Recently Modified Definitions</h4>
          <div className="recent-list">
            {stats.recentlyModified.length > 0 ? (
              stats.recentlyModified.map((def, index) => (
                <div key={getValue(def.sys_id)} className="recent-item">
                  <div className="recent-name">
                    {getDisplayValue(def.export_name)}
                  </div>
                  <div className="recent-details">
                    <span className={`status ${String(def.active) === 'true' ? 'active' : 'inactive'}`}>
                      {String(def.active) === 'true' ? 'Active' : 'Inactive'}
                    </span>
                    <span className="modified-date">
                      {new Date(getValue(def.sys_updated_on)).toLocaleDateString()}
                    </span>
                  </div>
                </div>
              ))
            ) : (
              <div className="no-data">No definitions found</div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}","import React, { useMemo } from 'react';
import './ExecutionMetrics.css';

export default function ExecutionMetrics({ logs }) {
  const metrics = useMemo(() => {
    const getValue = (field) => typeof field === 'object' ? field.value : field;
    const getDisplayValue = (field) => typeof field === 'object' ? field.display_value : field;

    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const weekAgo = new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000);
    const monthAgo = new Date(today.getTime() - 30 * 24 * 60 * 60 * 1000);

    const todayLogs = logs.filter(log => {
      const logDate = new Date(getValue(log.execution_start));
      return logDate >= today;
    });

    const weekLogs = logs.filter(log => {
      const logDate = new Date(getValue(log.execution_start));
      return logDate >= weekAgo;
    });

    const monthLogs = logs.filter(log => {
      const logDate = new Date(getValue(log.execution_start));
      return logDate >= monthAgo;
    });

    const calculateStats = (logSet) => {
      const total = logSet.length;
      const successful = logSet.filter(log => String(log.success) === 'true').length;
      const failed = total - successful;
      const successRate = total > 0 ? (successful / total * 100).toFixed(1) : 0;

      const durations = logSet
        .map(log => parseFloat(getValue(log.duration_ms)) || 0)
        .filter(d => d > 0);
      const avgRuntime = durations.length > 0 
        ? (durations.reduce((sum, d) => sum + d, 0) / durations.length).toFixed(0)
        : 0;

      const totalRecords = logSet.reduce((sum, log) => {
        return sum + (parseInt(getValue(log.records_exported)) || 0);
      }, 0);

      return { total, successful, failed, successRate, avgRuntime, totalRecords };
    };

    return {
      today: calculateStats(todayLogs),
      week: calculateStats(weekLogs),
      month: calculateStats(monthLogs)
    };
  }, [logs]);

  const chartData = useMemo(() => {
    const getValue = (field) => typeof field === 'object' ? field.value : field;
    const dailyStats = {};

    logs.forEach(log => {
      const date = getValue(log.execution_start)?.split(' ')[0];
      if (date) {
        if (!dailyStats[date]) {
          dailyStats[date] = { successful: 0, failed: 0, total: 0 };
        }
        dailyStats[date].total++;
        if (String(log.success) === 'true') {
          dailyStats[date].successful++;
        } else {
          dailyStats[date].failed++;
        }
      }
    });

    return Object.entries(dailyStats)
      .sort(([a], [b]) => new Date(a) - new Date(b))
      .slice(-14); // Last 14 days
  }, [logs]);

  return (
    <div className="execution-metrics">
      <div className="metrics-grid">
        <div className="metric-period">
          <h4>Today</h4>
          <div className="metric-stats">
            <div className="metric-item">
              <span className="metric-value">{metrics.today.total}</span>
              <span className="metric-label">Total Exports</span>
            </div>
            <div className="metric-item success">
              <span className="metric-value">{metrics.today.successful}</span>
              <span className="metric-label">Successful</span>
            </div>
            <div className="metric-item failed">
              <span className="metric-value">{metrics.today.failed}</span>
              <span className="metric-label">Failed</span>  
            </div>
            <div className="metric-item">
              <span className="metric-value">{metrics.today.successRate}%</span>
              <span className="metric-label">Success Rate</span>
            </div>
          </div>
        </div>

        <div className="metric-period">
          <h4>This Week</h4>
          <div className="metric-stats">
            <div className="metric-item">
              <span className="metric-value">{metrics.week.total}</span>
              <span className="metric-label">Total Exports</span>
            </div>
            <div className="metric-item">
              <span className="metric-value">{metrics.week.avgRuntime}ms</span>
              <span className="metric-label">Avg Runtime</span>
            </div>
            <div className="metric-item">
              <span className="metric-value">{metrics.week.totalRecords.toLocaleString()}</span>
              <span className="metric-label">Records Exported</span>
            </div>
            <div className="metric-item">
              <span className="metric-value">{metrics.week.successRate}%</span>
              <span className="metric-label">Success Rate</span>
            </div>
          </div>
        </div>

        <div className="metric-period">
          <h4>This Month</h4>
          <div className="metric-stats">
            <div className="metric-item">
              <span className="metric-value">{metrics.month.total}</span>
              <span className="metric-label">Total Exports</span>
            </div>
            <div className="metric-item">
              <span className="metric-value">{metrics.month.avgRuntime}ms</span>
              <span className="metric-label">Avg Runtime</span>
            </div>
            <div className="metric-item">
              <span className="metric-value">{metrics.month.totalRecords.toLocaleString()}</span>
              <span className="metric-label">Records Exported</span>
            </div>
            <div className="metric-item">
              <span className="metric-value">{metrics.month.successRate}%</span>
              <span className="metric-label">Success Rate</span>
            </div>
          </div>
        </div>
      </div>

      <div className="chart-section">
        <h4>Daily Export Activity (Last 14 Days)</h4>
        <div className="column-chart">
          {chartData.length > 0 ? (
            chartData.map(([date, stats]) => {
              const maxHeight = Math.max(...chartData.map(([, s]) => s.total));
              const height = maxHeight > 0 ? (stats.total / maxHeight) * 100 : 0;

              return (
                <div key={date} className="chart-column">
                  <div className="column-bar" style={{ height: `${height}%` }}>
                    <div className="bar-successful" 
                         style={{ height: `${stats.total > 0 ? (stats.successful / stats.total) * 100 : 0}%` }}>
                    </div>
                    <div className="bar-failed" 
                         style={{ height: `${stats.total > 0 ? (stats.failed / stats.total) * 100 : 0}%` }}>
                    </div>
                  </div>
                  <div className="column-label">
                    {new Date(date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
                  </div>
                  <div className="column-value">{stats.total}</div>
                </div>
              );
            })
          ) : (
            <div className="no-chart-data">No execution data available for the last 14 days</div>
          )}
        </div>
      </div>
    </div>
  );
}","import React, { useMemo } from 'react';

export default function ErrorInsights({ logs }) {
  const errorAnalysis = useMemo(() => {
    const getValue = (field) => typeof field === 'object' ? field.value : field;
    const getDisplayValue = (field) => typeof field === 'object' ? field.display_value : field;

    const failedLogs = logs.filter(log => String(log.success) === 'false');

    // Recent failed exports (last 10)
    const recentFailures = failedLogs
      .sort((a, b) => new Date(getValue(b.execution_start)) - new Date(getValue(a.execution_start)))
      .slice(0, 10);

    // Error type distribution
    const errorTypes = {};
    failedLogs.forEach(log => {
      const errorMsg = getDisplayValue(log.error_message) || 'Unknown Error';
      const errorType = errorMsg.split(':')[0] || errorMsg.substring(0, 50);
      errorTypes[errorType] = (errorTypes[errorType] || 0) + 1;
    });

    const sortedErrorTypes = Object.entries(errorTypes)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 8);

    return {
      totalFailures: failedLogs.length,
      recentFailures,
      errorTypes: sortedErrorTypes
    };
  }, [logs]);

  const getValue = (field) => typeof field === 'object' ? field.value : field;
  const getDisplayValue = (field) => typeof field === 'object' ? field.display_value : field;

  return (
    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '25px' }}>
      <div>
        <h4 style={{ margin: '0 0 15px 0', color: '#4a5568' }}>Recent Failed Exports</h4>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px', maxHeight: '400px', overflowY: 'auto' }}>
          {errorAnalysis.recentFailures.length > 0 ? (
            errorAnalysis.recentFailures.map((log, index) => (
              <div key={getValue(log.sys_id)} style={{
                background: '#fed7d7',
                border: '1px solid #fc8181',
                borderRadius: '6px',
                padding: '12px',
                fontSize: '0.9rem'
              }}>
                <div style={{ fontWeight: '600', color: '#c53030', marginBottom: '5px' }}>
                  {getDisplayValue(log.export_definition)}
                </div>
                <div style={{ color: '#2d3748', marginBottom: '5px', fontSize: '0.8rem' }}>
                  {new Date(getValue(log.execution_start)).toLocaleString()}
                </div>
                <div style={{ color: '#c53030', fontSize: '0.8rem' }}>
                  {getDisplayValue(log.error_message) || 'Unknown error'}
                </div>
              </div>
            ))
          ) : (
            <div style={{ 
              textAlign: 'center', 
              padding: '20px', 
              color: '#718096', 
              fontStyle: 'italic',
              background: '#f8f9fa',
              borderRadius: '6px'
            }}>
              No recent failures found
            </div>
          )}
        </div>
      </div>

      <div>
        <h4 style={{ margin: '0 0 15px 0', color: '#4a5568' }}>
          Error Type Distribution ({errorAnalysis.totalFailures} total failures)
        </h4>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          {errorAnalysis.errorTypes.length > 0 ? (
            errorAnalysis.errorTypes.map(([errorType, count]) => {
              const percentage = errorAnalysis.totalFailures > 0 
                ? ((count / errorAnalysis.totalFailures) * 100).toFixed(1)
                : 0;

              return (
                <div key={errorType} style={{ 
                  background: '#f8f9fa', 
                  borderRadius: '6px', 
                  padding: '10px',
                  border: '1px solid #e2e8f0'
                }}>
                  <div style={{ 
                    display: 'flex', 
                    justifyContent: 'space-between', 
                    alignItems: 'center',
                    marginBottom: '5px'
                  }}>
                    <span style={{ fontWeight: '600', fontSize: '0.9rem', color: '#2d3748' }}>
                      {errorType}
                    </span>
                    <span style={{ fontSize: '0.8rem', color: '#718096' }}>
                      {count} ({percentage}%)
                    </span>
                  </div>
                  <div style={{ 
                    background: '#e2e8f0', 
                    height: '6px', 
                    borderRadius: '3px', 
                    overflow: 'hidden' 
                  }}>
                    <div style={{
                      background: '#e53e3e',
                      height: '100%',
                      width: `${percentage}%`,
                      borderRadius: '3px',
                      transition: 'width 0.3s ease'
                    }}></div>
                  </div>
                </div>
              );
            })
          ) : (
            <div style={{ 
              textAlign: 'center', 
              padding: '20px', 
              color: '#718096', 
              fontStyle: 'italic',
              background: '#f8f9fa',
              borderRadius: '6px'
            }}>
              No error data available
            </div>
          )}
        </div>
      </div>
    </div>
  );
}","import React, { useMemo } from 'react';

export default function ConfigurationQuality({ definitions, mappings, relatedSources }) {
  const qualityMetrics = useMemo(() => {
    const getValue = (field) => typeof field === 'object' ? field.value : field;
    const getDisplayValue = (field) => typeof field === 'object' ? field.display_value : field;

    // Group mappings by export definition
    const mappingsByDef = {};
    mappings.forEach(mapping => {
      const defId = getValue(mapping.export_definition);
      if (!mappingsByDef[defId]) {
        mappingsByDef[defId] = [];
      }
      mappingsByDef[defId].push(mapping);
    });

    // Group related sources by export definition  
    const sourcesByDef = {};
    relatedSources.forEach(source => {
      const defId = getValue(source.export_definition);
      if (!sourcesByDef[defId]) {
        sourcesByDef[defId] = [];
      }
      sourcesByDef[defId].push(source);
    });

    let missingMappings = 0;
    let missingSources = 0;
    let emptyQueries = 0;
    const issues = [];

    definitions.forEach(def => {
      const defId = getValue(def.sys_id);
      const defName = getDisplayValue(def.export_name);

      // Check for missing mappings
      if (!mappingsByDef[defId] || mappingsByDef[defId].length === 0) {
        missingMappings++;
        issues.push({
          type: 'Missing Mappings',
          definition: defName,
          description: 'No field mappings configured'
        });
      }

      // Check for definitions that use related sources but don't have any
      const hasRelatedMappings = mappingsByDef[defId]?.some(m => 
        getDisplayValue(m.source_type) === 'related' && getValue(m.source_table_alias)
      );

      if (hasRelatedMappings && (!sourcesByDef[defId] || sourcesByDef[defId].length === 0)) {
        missingSources++;
        issues.push({
          type: 'Missing Related Sources',
          definition: defName,
          description: 'Has related field mappings but no related sources defined'
        });
      }

      // Check for empty or invalid queries
      const encodedQuery = getValue(def.encoded_query) || '';
      const filterScript = getValue(def.filter_script) || '';

      if (!encodedQuery.trim() && !filterScript.trim()) {
        emptyQueries++;
        issues.push({
          type: 'No Filtering',
          definition: defName,
          description: 'No encoded query or filter script specified'
        });
      }
    });

    return {
      totalDefinitions: definitions.length,
      missingMappings,
      missingSources,
      emptyQueries,
      issues: issues.slice(0, 10), // Show top 10 issues
      qualityScore: definitions.length > 0 
        ? Math.round(((definitions.length - issues.length) / definitions.length) * 100)
        : 100
    };
  }, [definitions, mappings, relatedSources]);

  return (
    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '25px' }}>
      <div>
        <h4 style={{ margin: '0 0 15px 0', color: '#4a5568' }}>Configuration Quality Score</h4>

        <div style={{ 
          textAlign: 'center', 
          marginBottom: '20px',
          background: 'linear-gradient(135deg, #f0f2ff, #e6eafe)',
          padding: '20px',
          borderRadius: '12px',
          border: '1px solid #e2e8f0'
        }}>
          <div style={{ 
            fontSize: '3rem', 
            fontWeight: '700',
            color: qualityMetrics.qualityScore >= 80 ? '#48bb78' : 
                   qualityMetrics.qualityScore >= 60 ? '#ed8936' : '#e53e3e'
          }}>
            {qualityMetrics.qualityScore}%
          </div>
          <div style={{ color: '#718096', fontSize: '0.9rem', fontWeight: '600' }}>
            OVERALL QUALITY
          </div>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <div style={{
            background: '#fed7cc',
            border: '1px solid #fc8181',
            borderRadius: '8px',
            padding: '12px',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center'
          }}>
