export default function TopExportProfiles({ definitions, logs }) {
  const exportProfiles = useMemo(() => {
    const getValue = (field) => typeof field === 'object' ? field.value : field;
    const getDisplayValue = (field) => typeof field === 'object' ? field.display_value : field;

    // Count executions per definition
    const executionCounts = {};
    const recentExecutions = {};

    logs.forEach(log => {
      const defId = getValue(log.export_definition);
      const defName = getDisplayValue(log.export_definition);

      if (!executionCounts[defId]) {
        executionCounts[defId] = { name: defName, count: 0, successful: 0 };
      }

      executionCounts[defId].count++;
      if (String(log.success) === 'true') {
        executionCounts[defId].successful++;
      }

      // Track most recent execution
      const executionDate = new Date(getValue(log.execution_start));
      if (!recentExecutions[defId] || executionDate > recentExecutions[defId].date) {
        recentExecutions[defId] = {
          name: defName,
          date: executionDate,
          success: String(log.success) === 'true',
          records: parseInt(getValue(log.records_exported)) || 0
        };
      }
    });

    // Most frequently used (top 10)
    const mostUsed = Object.entries(executionCounts)
      .sort(([,a], [,b]) => b.count - a.count)
      .slice(0, 10)
      .map(([id, data]) => ({
        id,
        name: data.name,
        executions: data.count,
        successRate: data.count > 0 ? ((data.successful / data.count) * 100).toFixed(1) : 0
      }));

    // Recently executed (top 10)
    const recentlyExecuted = Object.entries(recentExecutions)
      .sort(([,a], [,b]) => b.date - a.date)
      .slice(0, 10)
      .map(([id, data]) => ({
        id,
        name: data.name,
        lastExecution: data.date,
        lastSuccess: data.success,
        lastRecords: data.records
      }));

    return { mostUsed, recentlyExecuted };
  }, [definitions, logs]);

  return (
    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '25px' }}>
      <div>
        <h4 style={{ margin: '0 0 15px 0', color: '#4a5568' }}>Most Frequently Used Exports</h4>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          {exportProfiles.mostUsed.length > 0 ? (
            exportProfiles.mostUsed.map((profile, index) => (
              <div key={profile.id} style={{
                background: '#f8f9fa',
                border: '1px solid #e2e8f0',
                borderRadius: '8px',
                padding: '12px',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center'
              }}>
                <div>
                  <div style={{ 
                    fontWeight: '600', 
                    color: '#2d3748', 
                    fontSize: '0.9rem',
                    marginBottom: '2px'
                  }}>
                    #{index + 1} {profile.name}
                  </div>
                  <div style={{ fontSize: '0.8rem', color: '#718096' }}>
                    {profile.executions} executions • {profile.successRate}% success rate
                  </div>
                </div>
                <div style={{
                  background: profile.successRate >= 80 ? '#c6f6d5' : 
                            profile.successRate >= 60 ? '#feebc8' : '#fed7d7',
                  color: profile.successRate >= 80 ? '#22543d' : 
                         profile.successRate >= 60 ? '#c05621' : '#c53030',
                  padding: '4px 8px',
                  borderRadius: '4px',
                  fontSize: '0.8rem',
                  fontWeight: '600'
                }}>
                  {profile.executions}
                </div>
              </div>
            ))
          ) : (
            <div style={{ 
              textAlign: 'center', 
              padding: '20px', 
              color: '#718096', 
              fontStyle: 'italic',
              background: '#f8f9fa',
              borderRadius: '6px'
            }}>
              No execution data available
            </div>
          )}
        </div>
      </div>

      <div>
        <h4 style={{ margin: '0 0 15px 0', color: '#4a5568' }}>Recently Executed Exports</h4>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          {exportProfiles.recentlyExecuted.length > 0 ? (
            exportProfiles.recentlyExecuted.map((profile) => (
              <div key={profile.id} style={{
                background: '#f8f9fa',
                border: '1px solid #e2e8f0',
                borderRadius: '8px',
                padding: '12px'
              }}>
                <div style={{ 
                  display: 'flex', 
                  justifyContent: 'space-between', 
                  alignItems: 'flex-start',
                  marginBottom: '5px'
                }}>
                  <div style={{ 
                    fontWeight: '600', 
                    color: '#2d3748', 
                    fontSize: '0.9rem'
                  }}>
                    {profile.name}
                  </div>
                  <div style={{
                    background: profile.lastSuccess ? '#c6f6d5' : '#fed7d7',
                    color: profile.lastSuccess ? '#22543d' : '#c53030',
                    padding: '2px 6px',
                    borderRadius: '3px',
                    fontSize: '0.7rem',
                    fontWeight: '600'
                  }}>
                    {profile.lastSuccess ? 'SUCCESS' : 'FAILED'}
                  </div>
                </div>
                <div style={{ fontSize: '0.8rem', color: '#718096', marginBottom: '2px' }}>
                  {profile.lastExecution.toLocaleString()}
                </div>
                <div style={{ fontSize: '0.8rem', color: '#718096' }}>
                  {profile.lastRecords.toLocaleString()} records exported
                </div>
              </div>
            ))
          ) : (
            <div style={{ 
              textAlign: 'center', 
              padding: '20px', 
              color: '#718096', 
              fontStyle: 'italic',
              background: '#f8f9fa',
              borderRadius: '6px'
            }}>
              No recent execution data available
            </div>
          )}
        </div>
      </div>
    </div>
  );
