          />
        </section>

        {/* Section 5: Top Export Profiles */}
        <section className="dashboard-section">
          <h2>Top Export Profiles</h2>
          <TopExportProfiles 
            definitions={dashboardData.definitions}
            logs={dashboardData.executionLogs}
          />
        </section>
      </div>
    </div>
  );
